import { useState, useMemo, useRef, useEffect } from "react";

const LOGO_SRC = "data:image/png;base64,";

const BRAND = { navy: "#0B1E3D", green: "#AAFF00", white: "#F8FAF7", slate: "#8A9BB0" };

const EXERCISES = [
  { name: "Machine Chest Press", primary: "Chest", secondary: ["Triceps"] },
  { name: "Incline Machine Press", primary: "Chest", secondary: ["Front Delts"] },
  { name: "Cable Fly", primary: "Chest", secondary: [] },
  { name: "Lat Pulldown", primary: "Back", secondary: ["Biceps"] },
  { name: "Seated Cable Row", primary: "Back", secondary: ["Rear Delts"] },
  { name: "Machine Row", primary: "Back", secondary: ["Biceps"] },
  { name: "Leg Press", primary: "Quads", secondary: ["Glutes"] },
  { name: "Hack Squat", primary: "Quads", secondary: ["Glutes"] },
  { name: "Leg Extension", primary: "Quads", secondary: [] },
  { name: "Seated Leg Curl", primary: "Hamstrings", secondary: ["Glutes"] },
  { name: "Lying Leg Curl", primary: "Hamstrings", secondary: [] },
  { name: "Hip Thrust Machine", primary: "Glutes", secondary: ["Hamstrings"] },
  { name: "Lateral Raise Machine", primary: "Side Delts", secondary: [] },
  { name: "Cable Lateral Raise", primary: "Side Delts", secondary: [] },
  { name: "Reverse Pec Deck", primary: "Rear Delts", secondary: ["Back"] },
  { name: "Face Pull", primary: "Rear Delts", secondary: ["Rear Delts"] },
  { name: "Cable Curl", primary: "Biceps", secondary: [] },
  { name: "Machine Preacher Curl", primary: "Biceps", secondary: [] },
  { name: "Rope Pressdown", primary: "Triceps", secondary: [] },
  { name: "Overhead Cable Extension", primary: "Triceps", secondary: [] },
  { name: "Standing Calf Raise", primary: "Calves", secondary: [] },
  { name: "Cable Crunch", primary: "Core", secondary: [] },
];

const MUSCLES = ["Chest","Back","Quads","Hamstrings","Glutes","Side Delts","Rear Delts","Biceps","Triceps","Calves","Core"];

const DEMO_LOGS = [
  { id: 1, date: "2026-04-20", exercise: "Machine Chest Press", muscle: "Chest", sets: [{ reps: 10, load: 180, rir: 2 }, { reps: 10, load: 185, rir: 2 }, { reps: 9, load: 185, rir: 1 }], pain: false, notes: "" },
  { id: 2, date: "2026-04-20", exercise: "Cable Fly", muscle: "Chest", sets: [{ reps: 12, load: 80, rir: 1 }, { reps: 11, load: 80, rir: 0 }, { reps: 10, load: 80, rir: 0 }], pain: false, notes: "" },
  { id: 3, date: "2026-04-21", exercise: "Lat Pulldown", muscle: "Back", sets: [{ reps: 11, load: 160, rir: 2 }, { reps: 11, load: 165, rir: 1 }, { reps: 10, load: 165, rir: 1 }, { reps: 9, load: 165, rir: 0 }], pain: false, notes: "" },
  { id: 4, date: "2026-04-21", exercise: "Seated Cable Row", muscle: "Back", sets: [{ reps: 12, load: 140, rir: 2 }, { reps: 12, load: 145, rir: 1 }, { reps: 11, load: 145, rir: 1 }], pain: false, notes: "" },
  { id: 5, date: "2026-04-22", exercise: "Leg Press", muscle: "Quads", sets: [{ reps: 10, load: 360, rir: 3 }, { reps: 10, load: 380, rir: 2 }, { reps: 9, load: 380, rir: 1 }, { reps: 8, load: 380, rir: 0 }], pain: false, notes: "" },
  { id: 6, date: "2026-04-22", exercise: "Seated Leg Curl", muscle: "Hamstrings", sets: [{ reps: 8, load: 115, rir: 1 }, { reps: 7, load: 115, rir: 0 }, { reps: 7, load: 110, rir: 0 }], pain: true, notes: "Left hamstring pull at end of set 2" },
  { id: 7, date: "2026-04-23", exercise: "Lateral Raise Machine", muscle: "Side Delts", sets: [{ reps: 15, load: 70, rir: 2 }, { reps: 14, load: 70, rir: 1 }, { reps: 13, load: 70, rir: 0 }], pain: false, notes: "" },
  { id: 8, date: "2026-04-23", exercise: "Reverse Pec Deck", muscle: "Rear Delts", sets: [{ reps: 15, load: 85, rir: 2 }, { reps: 14, load: 85, rir: 1 }, { reps: 13, load: 85, rir: 0 }], pain: false, notes: "" },
  { id: 9, date: "2026-04-24", exercise: "Cable Curl", muscle: "Biceps", sets: [{ reps: 12, load: 60, rir: 2 }, { reps: 12, load: 62, rir: 1 }, { reps: 11, load: 62, rir: 0 }], pain: false, notes: "" },
  { id: 10, date: "2026-04-24", exercise: "Rope Pressdown", muscle: "Triceps", sets: [{ reps: 15, load: 75, rir: 2 }, { reps: 14, load: 75, rir: 1 }, { reps: 13, load: 75, rir: 0 }], pain: false, notes: "" },
];

const DEMO_CHECKIN = { sleep: 7, recovery: 6, soreness: 5, motivation: 7, jointPain: 3, hrv: 62, restingHR: 52, notes: "" };

function calcVolume1RM(load, reps, rir = 0) {
  const repsToFailure = reps + rir;
  return load * (1 + repsToFailure / 30);
}

function getWeeklyVolume(logs) {
  const vol = {};
  MUSCLES.forEach(m => { vol[m] = { sets: 0, e1rm: [] }; });
  logs.forEach(log => {
    const sets = log.sets || [];
    vol[log.muscle].sets += sets.length;
    sets.forEach(s => vol[log.muscle].e1rm.push(calcVolume1RM(s.load, s.reps, s.rir)));
  });
  return vol;
}

const TABS = [
  { id: "dashboard", label: "Overview" },
  { id: "log", label: "Log" },
  { id: "history", label: "History" },
  { id: "checkin", label: "Check-in" },
  { id: "ai", label: "AI Coach" },
];

export default function ReclaimTrainingOS() {
  const [tab, setTab] = useState("dashboard");
  const [logs, setLogs] = useState(DEMO_LOGS);
  const [checkIn, setCheckIn] = useState(DEMO_CHECKIN);
  const [form, setForm] = useState({ exercise: EXERCISES[0].name, sets: [{ reps: 10, load: 100, rir: 2 }], pain: false, notes: "", date: new Date().toISOString().slice(0, 10) });
  const [aiMessages, setAiMessages] = useState([]);
  const [aiInput, setAiInput] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [muscleFilter, setMuscleFilter] = useState(null);
  const chatEndRef = useRef(null);

  const volume = useMemo(() => getWeeklyVolume(logs), [logs]);
  const totalSets = Object.values(volume).reduce((s, v) => s + v.sets, 0);
  const painCount = logs.filter(l => l.pain).length;
  const avgRecovery = ((checkIn.sleep + checkIn.recovery) / 2).toFixed(1);

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [aiMessages]);

  function addSet() {
    const prev = form.sets[form.sets.length - 1];
    setForm(f => ({ ...f, sets: [...f.sets, { ...prev }] }));
  }

  function updateSet(i, field, val) {
    setForm(f => {
      const sets = [...f.sets];
      sets[i] = { ...sets[i], [field]: Number(val) };
      return { ...f, sets };
    });
  }

  function removeSet(i) {
    if (form.sets.length <= 1) return;
    setForm(f => ({ ...f, sets: f.sets.filter((_, idx) => idx !== i) }));
  }

  function submitLog() {
    if (!form.exercise || form.sets.length === 0) return;
    const ex = EXERCISES.find(e => e.name === form.exercise);
    const newLog = {
      id: Date.now(),
      date: form.date,
      exercise: form.exercise,
      muscle: ex?.primary || "Chest",
      sets: form.sets.map(s => ({ reps: Number(s.reps) || 0, load: Number(s.load) || 0, rir: Number(s.rir) || 0 })),
      pain: form.pain,
      notes: form.notes,
    };
    setLogs(prev => [newLog, ...prev]);
    setForm(f => ({ ...f, sets: [{ reps: 10, load: 100, rir: 2 }], pain: false, notes: "" }));
  }

  async function sendAiMessage() {
    if (!aiInput.trim() || aiLoading) return;
    const userMsg = aiInput.trim();
    setAiInput("");
    const newMessages = [...aiMessages, { role: "user", content: userMsg }];
    setAiMessages(newMessages);
    setAiLoading(true);

    const context = buildAIContext();
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: `You are RECLAIM Coach, an expert evidence-based strength training advisor for a male pharmacist-athlete. He is 6'2", ~208 lbs, training for muscle building and fat loss with a hockey performance secondary goal. He prefers machine-based training, follows push/pull/legs, and has a shoulder separation (right, not fully recovered) and chronic hamstring tightness. Be direct, concise, and evidence-based. No fluff, no motivational platitudes. Use RIR (reps in reserve) framework. Cite mechanisms briefly when relevant. Max 250 words per response unless asked for more.\n\nCurrent training data:\n${context}`,
          messages: newMessages.map(m => ({ role: m.role, content: m.content })),
        }),
      });
      const data = await response.json();
      const reply = data.content?.[0]?.text || "Something went wrong with the API.";
      setAiMessages([...newMessages, { role: "assistant", content: reply }]);
    } catch {
      setAiMessages([...newMessages, { role: "assistant", content: "Connection error. Check your API access." }]);
    }
    setAiLoading(false);
  }

  function buildAIContext() {
    const volSummary = MUSCLES.map(m => `${m}: ${volume[m]?.sets || 0} sets`).join(", ");
    const recentLogs = logs.slice(0, 8).map(l => {
      const setStr = l.sets.map(s => `${s.reps}x${s.load}lb@${s.rir}RIR`).join(" / ");
      return `${l.date} - ${l.exercise} [${l.muscle}]: ${setStr}${l.pain ? " [PAIN FLAG]" : ""}${l.notes ? ` Note: ${l.notes}` : ""}`;
    }).join("\n");
    return `\nWeekly volume: ${volSummary}\nTotal hard sets: ${totalSets}\nPain flags this week: ${painCount}\nCheck-in: Sleep ${checkIn.sleep}/10, Recovery ${checkIn.recovery}/10, Soreness ${checkIn.soreness}/10, Joint pain ${checkIn.jointPain}/10, Motivation ${checkIn.motivation}/10${checkIn.hrv ? `, HRV ${checkIn.hrv}ms` : ""}${checkIn.restingHR ? `, RHR ${checkIn.restingHR}bpm` : ""}\nRecent sessions:\n${recentLogs}`;
  }

  function quickPrompt(text) {
    setAiInput(text);
    setTab("ai");
  }

  const systemStatus = checkIn.jointPain >= 7 || checkIn.recovery <= 4
    ? { label: "Pull back", color: "#FF4444" }
    : checkIn.recovery >= 7 && checkIn.sleep >= 7
    ? { label: "Increase ready", color: BRAND.green }
    : { label: "Hold steady", color: "#FFB800" };

  return (
    <div style={{ minHeight: "100vh", background: "#0A0F1A", color: "#E8EEF5", fontFamily: "'DM Sans', system-ui, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,700;0,9..40,800;1,9..40,400&family=DM+Mono:wght@400;500&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::-webkit-scrollbar { width: 4px; } ::-webkit-scrollbar-track { background: transparent; } ::-webkit-scrollbar-thumb { background: #2A3550; border-radius: 2px; }
        input[type=number]::-webkit-inner-spin-button { opacity: 0.4; }
        .tab-btn { background: none; border: none; padding: 8px 16px; border-radius: 8px; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 500; color: #5A6E8A; transition: all 0.15s; white-space: nowrap; }
        .tab-btn.active { background: ${BRAND.green}22; color: ${BRAND.green}; }
        .tab-btn:hover:not(.active) { color: #C8D8E8; background: #1A2540; }
        .card { background: #111827; border: 1px solid #1E2D45; border-radius: 16px; padding: 20px; }
        .muscle-bar { height: 6px; background: #1A2540; border-radius: 3px; overflow: hidden; }
        .muscle-bar-fill { height: 100%; border-radius: 3px; background: ${BRAND.green}; transition: width 0.5s ease; }
        .btn-primary { background: ${BRAND.green}; color: #0A0F1A; border: none; padding: 10px 20px; border-radius: 10px; font-family: inherit; font-size: 14px; font-weight: 700; cursor: pointer; transition: opacity 0.15s; }
        .btn-primary:hover { opacity: 0.88; }
        .btn-secondary { background: #1A2540; color: #C8D8E8; border: 1px solid #1E2D45; padding: 10px 20px; border-radius: 10px; font-family: inherit; font-size: 14px; font-weight: 500; cursor: pointer; transition: all 0.15s; }
        .btn-secondary:hover { border-color: #2E4060; background: #1E2D45; }
        .input-field { background: #0D1520; border: 1px solid #1E2D45; border-radius: 10px; padding: 10px 14px; color: #E8EEF5; font-family: inherit; font-size: 14px; width: 100%; transition: border-color 0.15s; outline: none; }
        .input-field:focus { border-color: ${BRAND.green}66; }
        select.input-field option { background: #111827; }
        .set-row { display: grid; grid-template-columns: 1fr 1fr 1fr 32px; gap: 8px; align-items: end; }
        .label { font-size: 11px; font-weight: 500; color: #5A6E8A; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 6px; }
        .pain-badge { background: #FF444420; color: #FF7777; font-size: 11px; font-weight: 600; padding: 3px 8px; border-radius: 5px; border: 1px solid #FF444430; }
        .stat-num { font-size: 32px; font-weight: 800; letter-spacing: -0.03em; line-height: 1; color: #E8EEF5; }
        .stat-label { font-size: 12px; color: #5A6E8A; margin-top: 4px; }
        .chat-user { background: #1A2540; border-radius: 12px 12px 4px 12px; padding: 12px 16px; max-width: 80%; margin-left: auto; font-size: 14px; line-height: 1.6; }
        .chat-ai { background: #111827; border: 1px solid #1E2D45; border-radius: 12px 12px 12px 4px; padding: 12px 16px; max-width: 88%; font-size: 14px; line-height: 1.7; white-space: pre-wrap; }
        .chat-input-wrap { position: sticky; bottom: 0; background: #0A0F1A; padding: 16px 0 4px; }
        .quick-chip { background: #111827; border: 1px solid #1E2D45; border-radius: 20px; padding: 6px 14px; font-size: 12px; color: #8A9BB0; cursor: pointer; transition: all 0.15s; white-space: nowrap; font-family: inherit; }
        .quick-chip:hover { border-color: ${BRAND.green}66; color: ${BRAND.green}; }
        .quick-chip.active { border-color: ${BRAND.green}; color: ${BRAND.green}; background: ${BRAND.green}15; }
        .slider-wrap { margin: 8px 0; }
        input[type=range] { -webkit-appearance: none; width: 100%; height: 4px; border-radius: 2px; background: #1A2540; outline: none; }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; border-radius: 50%; background: ${BRAND.green}; cursor: pointer; }
        .log-card { transition: border-color 0.15s; }
        .log-card:hover { border-color: #2E4060; }
      `}</style>

      {/* Header */}
      <div style={{ background: "#0B1220", borderBottom: "1px solid #1E2D45", padding: "12px 20px" }}>
        <div style={{ maxWidth: 860, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <img
                src={LOGO_SRC}
                alt="RECLAIM Men's Health"
                style={{ width: 48, height: 48, borderRadius: 10, objectFit: "cover", background: "#0B1E3D" }}
              />
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, letterSpacing: "-0.02em", color: "#E8EEF5" }}>RECLAIM Training OS</div>
                <div style={{ fontSize: 11, color: BRAND.slate, fontFamily: "'DM Mono', monospace", marginTop: 1 }}>pharmacist-athlete protocol</div>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 7, height: 7, borderRadius: "50%", background: systemStatus.color }}></div>
              <span style={{ fontSize: 12, fontWeight: 600, color: systemStatus.color }}>{systemStatus.label}</span>
            </div>
          </div>
          <div style={{ display: "flex", gap: 4, marginTop: 12, overflowX: "auto", paddingBottom: 2 }}>
            {TABS.map(t => (
              <button key={t.id} className={`tab-btn${tab === t.id ? " active" : ""}`} onClick={() => setTab(t.id)}>{t.label}</button>
            ))}
          </div>
        </div>
      </div>

      {/* Content */}
      <div style={{ maxWidth: 860, margin: "0 auto", padding: "24px 20px 60px" }}>

        {tab === "dashboard" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 12 }}>
              {[
                { label: "Hard sets / wk", value: totalSets },
                { label: "Sessions logged", value: logs.length },
                { label: "Pain flags", value: painCount, alert: painCount > 0 },
                { label: "Avg recovery", value: `${avgRecovery}/10` },
              ].map(s => (
                <div key={s.label} className="card" style={s.alert && painCount > 0 ? { borderColor: "#FF444440" } : {}}>
                  <div className="stat-num" style={s.alert && painCount > 0 ? { color: "#FF7777" } : {}}>{s.value}</div>
                  <div className="stat-label">{s.label}</div>
                </div>
              ))}
            </div>

            <div className="card">
              <div style={{ fontSize: 13, fontWeight: 700, color: "#8A9BB0", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 16 }}>Weekly volume by muscle</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {MUSCLES.filter(m => volume[m]?.sets > 0).sort((a, b) => volume[b].sets - volume[a].sets).map(m => {
                  const sets = volume[m]?.sets || 0;
                  const maxSets = Math.max(...MUSCLES.map(x => volume[x]?.sets || 0), 1);
                  const pct = (sets / maxSets) * 100;
                  const hasPain = logs.some(l => l.muscle === m && l.pain);
                  return (
                    <div key={m}>
                      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4, alignItems: "center" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                          <span style={{ fontSize: 13, fontWeight: 500 }}>{m}</span>
                          {hasPain && <span className="pain-badge">pain</span>}
                        </div>
                        <span style={{ fontSize: 12, fontFamily: "'DM Mono', monospace", color: BRAND.slate }}>{sets} sets</span>
                      </div>
                      <div className="muscle-bar">
                        <div className="muscle-bar-fill" style={{ width: `${pct}%`, background: hasPain ? "#FF4444" : BRAND.green }} />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {checkIn.hrv && (
              <div className="card" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
                <div>
                  <div className="label">HRV (Pixel Watch)</div>
                  <div style={{ fontSize: 28, fontWeight: 800, color: checkIn.hrv > 55 ? BRAND.green : "#FFB800" }}>{checkIn.hrv} <span style={{ fontSize: 14, fontWeight: 400, color: BRAND.slate }}>ms</span></div>
                  <div style={{ fontSize: 12, color: BRAND.slate, marginTop: 4 }}>Manual entry from watch</div>
                </div>
                <div>
                  <div className="label">Resting HR</div>
                  <div style={{ fontSize: 28, fontWeight: 800, color: checkIn.restingHR < 60 ? BRAND.green : "#FFB800" }}>{checkIn.restingHR} <span style={{ fontSize: 14, fontWeight: 400, color: BRAND.slate }}>bpm</span></div>
                  <div style={{ fontSize: 12, color: BRAND.slate, marginTop: 4 }}>Manual entry from watch</div>
                </div>
              </div>
            )}

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              <button className="btn-secondary" style={{ textAlign: "center" }} onClick={() => quickPrompt("Based on my current weekly volume and check-in data, what should I adjust next session?")}>Ask AI: next session ↗</button>
              <button className="btn-secondary" style={{ textAlign: "center" }} onClick={() => quickPrompt("Which muscles need more volume and which are at risk of overtraining based on my logs?")}>Ask AI: volume audit ↗</button>
            </div>
          </div>
        )}

        {tab === "log" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            <div className="card">
              <div style={{ fontSize: 18, fontWeight: 800, marginBottom: 20 }}>Log session</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div>
                  <div className="label">Date</div>
                  <input type="date" className="input-field" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
                </div>
                <div>
                  <div className="label">Exercise</div>
                  <select className="input-field" value={form.exercise} onChange={e => setForm(f => ({ ...f, exercise: e.target.value }))}>
                    {EXERCISES.map(ex => <option key={ex.name} value={ex.name}>{ex.name} ({ex.primary})</option>)}
                  </select>
                </div>
                <div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                    <div className="label" style={{ marginBottom: 0 }}>Sets</div>
                    <button className="btn-secondary" style={{ padding: "4px 12px", fontSize: 12 }} onClick={addSet}>+ add set</button>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 32px", gap: 8, marginBottom: 8 }}>
                    {["Reps", "Load (lb)", "RIR", ""].map((h, i) => <div key={i} className="label" style={{ marginBottom: 0 }}>{h}</div>)}
                  </div>
                  {form.sets.map((set, i) => (
                    <div key={i} className="set-row" style={{ marginBottom: 8 }}>
                      <input type="number" min="1" max="50" className="input-field" value={set.reps} onChange={e => updateSet(i, "reps", e.target.value)} />
                      <input type="number" min="0" step="5" className="input-field" value={set.load} onChange={e => updateSet(i, "load", e.target.value)} />
                      <input type="number" min="0" max="5" className="input-field" value={set.rir} onChange={e => updateSet(i, "rir", e.target.value)} />
                      <button onClick={() => removeSet(i)} style={{ background: "#FF444420", border: "1px solid #FF444430", borderRadius: 8, color: "#FF7777", cursor: "pointer", height: 38, fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center" }}>×</button>
                    </div>
                  ))}
                </div>
                <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                  <input type="checkbox" checked={form.pain} onChange={e => setForm(f => ({ ...f, pain: e.target.checked }))} style={{ accentColor: "#FF4444", width: 16, height: 16 }} />
                  <span style={{ fontSize: 14, color: form.pain ? "#FF7777" : BRAND.slate }}>Pain or joint irritation flagged</span>
                </label>
                <div>
                  <div className="label">Session notes</div>
                  <textarea className="input-field" rows={2} placeholder="What felt different, what improved, anything notable..." value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} style={{ resize: "none" }} />
                </div>
                <button className="btn-primary" onClick={submitLog}>Save session</button>
              </div>
            </div>
          </div>
        )}

        {tab === "history" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 4 }}>
              <button className={`quick-chip${!muscleFilter ? " active" : ""}`} onClick={() => setMuscleFilter(null)}>All</button>
              {MUSCLES.filter(m => logs.some(l => l.muscle === m)).map(m => (
                <button key={m} className={`quick-chip${muscleFilter === m ? " active" : ""}`} onClick={() => setMuscleFilter(muscleFilter === m ? null : m)}>{m}</button>
              ))}
            </div>
            {logs.filter(l => !muscleFilter || l.muscle === muscleFilter).map(log => (
              <div key={log.id} className="card log-card">
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, marginBottom: 10 }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 15 }}>{log.exercise}</div>
                    <div style={{ fontSize: 12, color: BRAND.slate, marginTop: 2, fontFamily: "'DM Mono', monospace" }}>{log.date} · {log.muscle}</div>
                  </div>
                  {log.pain && <span className="pain-badge">pain flag</span>}
                </div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {log.sets.map((s, i) => (
                    <div key={i} style={{ background: "#0D1520", border: "1px solid #1A2540", borderRadius: 8, padding: "5px 10px", fontSize: 12, fontFamily: "'DM Mono', monospace" }}>
                      <span style={{ color: "#E8EEF5" }}>{s.reps}×{s.load}lb</span>
                      <span style={{ color: BRAND.slate }}> @{s.rir}RIR</span>
                    </div>
                  ))}
                </div>
                {log.notes && <div style={{ marginTop: 10, fontSize: 12, color: BRAND.slate, fontStyle: "italic", borderTop: "1px solid #1A2540", paddingTop: 8 }}>{log.notes}</div>}
                <div style={{ marginTop: 10 }}>
                  <button className="quick-chip" onClick={() => quickPrompt(`Analyze my ${log.exercise} session from ${log.date}: ${log.sets.map(s => `${s.reps}x${s.load}lb@${s.rir}RIR`).join(", ")}. What should I target next session?`)}>Ask AI about this session ↗</button>
                </div>
              </div>
            ))}
          </div>
        )}

        {tab === "checkin" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            <div className="card">
              <div style={{ fontSize: 18, fontWeight: 800, marginBottom: 4 }}>Weekly recovery check-in</div>
              <div style={{ fontSize: 13, color: BRAND.slate, marginBottom: 20 }}>This feeds the AI coach. Honest inputs, useful outputs.</div>
              {[
                { key: "sleep", label: "Sleep quality", lo: "Garbage", hi: "Optimal" },
                { key: "recovery", label: "Overall recovery", lo: "Wrecked", hi: "Fresh" },
                { key: "soreness", label: "Muscle soreness", lo: "Can't sit down", hi: "None" },
                { key: "motivation", label: "Training drive", lo: "Zero", hi: "Fired up" },
                { key: "jointPain", label: "Joint / injury pain", lo: "Significant", hi: "None" },
              ].map(item => (
                <div key={item.key} className="slider-wrap" style={{ marginBottom: 16 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                    <span style={{ fontSize: 14, fontWeight: 500 }}>{item.label}</span>
                    <span style={{ fontSize: 14, fontFamily: "'DM Mono', monospace", color: BRAND.green, fontWeight: 700 }}>{checkIn[item.key]}/10</span>
                  </div>
                  <input type="range" min="1" max="10" value={checkIn[item.key]} onChange={e => setCheckIn(c => ({ ...c, [item.key]: Number(e.target.value) }))} />
                  <div style={{ display: "flex", justifyContent: "space-between", marginTop: 4 }}>
                    <span style={{ fontSize: 11, color: "#5A6E8A" }}>{item.lo}</span>
                    <span style={{ fontSize: 11, color: "#5A6E8A" }}>{item.hi}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="card">
              <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, color: "#8A9BB0", textTransform: "uppercase", letterSpacing: "0.08em" }}>Pixel Watch metrics (manual entry)</div>
              <div style={{ fontSize: 12, color: BRAND.slate, marginBottom: 16 }}>Google Fit API requires a backend — enter watch data manually for now. The AI uses this for readiness assessment.</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                <div>
                  <div className="label">HRV (ms)</div>
                  <input type="number" className="input-field" value={checkIn.hrv} onChange={e => setCheckIn(c => ({ ...c, hrv: Number(e.target.value) }))} placeholder="e.g. 62" />
                </div>
                <div>
                  <div className="label">Resting HR (bpm)</div>
                  <input type="number" className="input-field" value={checkIn.restingHR} onChange={e => setCheckIn(c => ({ ...c, restingHR: Number(e.target.value) }))} placeholder="e.g. 52" />
                </div>
              </div>
            </div>
            <button className="btn-primary" onClick={() => quickPrompt("Based on my check-in data and current volume, what's your honest assessment of my recovery and what should I adjust?")}>Get AI recovery assessment ↗</button>
          </div>
        )}

        {tab === "ai" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ fontSize: 13, color: BRAND.slate }}>Powered by Claude Sonnet. Full context: your logs, volume, check-in, pain flags, training history, and injury profile.</div>
            {aiMessages.length === 0 && (
              <div>
                <div className="label" style={{ marginBottom: 10 }}>Quick prompts</div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {[
                    "What's my progressive overload target for next week?",
                    "Am I ready to add volume to chest or should I hold?",
                    "How should I manage my hamstring issue?",
                    "What's the optimal RIR range for my current phase?",
                    "Which muscles am I undertraining for hockey?",
                    "Should I deload this week based on my check-in?",
                  ].map(p => (
                    <button key={p} className="quick-chip" onClick={() => setAiInput(p)}>{p}</button>
                  ))}
                </div>
              </div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 12, minHeight: 200 }}>
              {aiMessages.map((msg, i) => (
                <div key={i} style={{ display: "flex", justifyContent: msg.role === "user" ? "flex-end" : "flex-start" }}>
                  <div className={msg.role === "user" ? "chat-user" : "chat-ai"}>
                    {msg.role === "assistant" && <div style={{ fontSize: 10, fontWeight: 700, color: BRAND.green, textTransform: "uppercase", letterSpacing: "0.12em", marginBottom: 6 }}>RECLAIM COACH</div>}
                    {msg.content}
                  </div>
                </div>
              ))}
              {aiLoading && (
                <div style={{ display: "flex", justifyContent: "flex-start" }}>
                  <div className="chat-ai">
                    <div style={{ fontSize: 10, fontWeight: 700, color: BRAND.green, textTransform: "uppercase", letterSpacing: "0.12em", marginBottom: 6 }}>RECLAIM COACH</div>
                    <div style={{ display: "flex", gap: 4, alignItems: "center" }}>
                      {[0,1,2].map(j => <div key={j} style={{ width: 6, height: 6, borderRadius: "50%", background: BRAND.green, animation: `pulse 1.2s ease-in-out ${j * 0.2}s infinite` }} />)}
                    </div>
                  </div>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>
            <div className="chat-input-wrap">
              <div style={{ display: "flex", gap: 8 }}>
                <input className="input-field" placeholder="Ask about training, volume, progressive loading, recovery..." value={aiInput} onChange={e => setAiInput(e.target.value)} onKeyDown={e => e.key === "Enter" && !e.shiftKey && sendAiMessage()} style={{ flex: 1 }} />
                <button className="btn-primary" onClick={sendAiMessage} disabled={aiLoading || !aiInput.trim()} style={{ opacity: aiLoading || !aiInput.trim() ? 0.5 : 1, padding: "10px 18px" }}>
                  {aiLoading ? "..." : "Send"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
      <style>{`@keyframes pulse { 0%, 100% { opacity: 0.3; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1); } }`}</style>
    </div>
  );
}
